      "原文": "紅箋小字，說盡平生意，鴻雁在雲魚在水，惆悵此情難寄。斜陽獨倚西樓，遙山恰對簾鉤。人面不知何處，綠波依舊東流。",
      "译文": "",
      "注释": "",
      "赏析": "以紅箋寄情之作。「鴻雁在雲魚在水，惆悵此情難寄」，音書難通的惆悵；結句「人面不知何處，綠波依舊東流」，物是人非之慨深婉。",
