      "原文": "燕鴻過後鶯歸去，細算浮生千萬緒。長於春夢幾多時，散似秋雲無覓處。聞琴解佩神仙侶，挽斷羅衣留不住。勸君莫作獨醒人，爛醉花間應有數。",
      "译文": "",
      "注释": "",
      "赏析": "惜春懷人之作。「長於春夢幾多時，散似秋雲無覓處」，以春夢秋雲喻歡會短暫、離散無蹤，感喟浮生。",
