      "原文": "祖席離歌，長亭別宴，香塵已隔猶回面。居人匹馬映林嘶，行人去棹依波轉。畫閣魂消，高樓目斷，斜陽只送平波遠。無窮無盡是離愁，天涯地角尋思遍。",
