      "上句": "鎖離愁連綿無際，來時陌上初燻，繡幃人念遠，暗垂珠露，泣送征輪",
      "下句": "鎖離愁連綿無際，來時陌上初燻，繡幃人念遠，暗垂珠露，泣送征輪。長行長在眼，更重重、遠水孤雲。但望極樓高，盡日目斷王孫。消魂，池塘別後，曾行處、綠妒輕裙。恁時攜素手，亂花飛絮裏，緩步香茵。朱顏空自改，向年年、芳意長新。遍綠野，嬉游醉眼，莫負青春。",
