      "标题": "曲玉管",
      "上句": "",
      "下句": "",
      "原文": "隴首雲飛，江邊日晚，煙波滿目憑闌久。一望關河蕭索，千里清秋，忍凝眸。杳杳神京，盈盈仙子，別來錦字終難偶。斷雁無憑，冉冉飛下汀洲，思悠悠。暗想當初，有多少、幽歡佳會；豈知聚散難期，翻成雨恨雲愁。阻追游，每登山臨水，惹起平生心事，一場消黯，永日無言，卻下層樓。",
      "译文": "",
      "注释": "",
      "赏析": "柳永羈旅懷人之作。「隴首雲飛，江邊日晚，煙波滿目憑闌久」，登臨眺遠；「一場消黯，永日無言，卻下層樓」，黯然銷魂之情溢於言表。",
