      "标题": "雨霖鈴",
      "上句": "寒蟬淒切，對長亭晚，驟雨初歇",
      "下句": "寒蟬淒切，對長亭晚，驟雨初歇。都門帳飲無緒，留戀處、蘭舟催發。執手相看淚眼，竟無語凝噎。念去去、千里煙波，暮靄沉沉楚天闊。多情自古傷離別，更那堪、冷落清秋節！今宵酒醒何處？楊柳岸、曉風殘月。此去經年，應是良辰好景虛設。便縱有千種風情，更與何人說。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
