      "上句": "佇倚危樓風細細，望極春愁，黯黯生天際",
      "下句": "佇倚危樓風細細，望極春愁，黯黯生天際。草色煙光殘照裏，無言誰會憑闌意？擬把疏狂圖一醉，對酒當歌，強樂還無味。衣帶漸寬終不悔。為伊消得人憔悴。",
