      "原文": "月華收，雲淡霜天曙。西征客、此時情苦。翠娥執手，送臨歧、軋軋開朱戶。千嬌面、盈盈佇立，無言有淚，斷腸爭忍回顧？一葉蘭舟，便恁急槳凌波去。貪行色、豈知離緒，萬般方寸，但飲恨、脈脈同誰語？更回首、重城不見，寒江天外，隱隱兩三煙樹。",
