      "原文": "夢覺透窗風一線，寒燈吹息。那堪酒醒，又聞空階夜雨頻滴。嗟因循、久作天涯客。負佳人、幾許盟言，便忍把、從前歡會，陡頓翻成憂戚。愁極。再三追思，洞房深處，幾度飲散歌闌，香暖鴛鴦被。豈暫時疏散，費伊心力，殢雲尤雨，有萬般千種，相憐相惜。恰到如今，天長漏永，無端自家疏隔。知何時、卻擁秦雲態？願低幃昵枕，輕輕細說與，江鄉夜夜，數寒更思憶。",
      "译文": "",
