      "赏析": "柳永羈旅長調，寫夢醒孤館的離愁。「那堪酒醒，又聞空階夜雨頻滴」，雨聲添愁；全詞回環往復，寫盡「江鄉夜夜，數寒更思憶」的苦況。",
