      "上句": "長安古道馬遲遲，高柳亂蟬嘶",
      "下句": "長安古道馬遲遲，高柳亂蟬嘶。夕陽島外，秋風原上，目斷四天垂。歸雲一去無蹤跡，何處是前期？狎興生疏，酒徒蕭索，不似去年時。",
      "原文": "",
