      "原文": "晚秋天，一霎微雨灑庭軒。檻菊蕭疏，井梧零亂，惹殘煙。淒然，望江關，飛雲黯淡夕陽閑。當時宋玉悲感，向此臨水與登山。遠道迢遞，行人淒楚，倦聽隴水潺湲。正蟬吟敗葉，蛩響衰草，相應喧喧。孤館度日如年，風露漸變，悄悄至更闌。長天淨，絳河清淺，皓月嬋娟。思綿綿，夜永對景，那堪屈指暗想從前。未名未祿，綺陌紅樓，往往經歲遷延。帝里風光好，當年少日，暮宴朝歡。況有狂朋怪侶，遇當歌對酒竟留連。別來迅景如梭，舊游似夢，煙水程何限？念利名、憔悴長縈絆，追往事、空慘愁顏。漏箭移，稍覺輕寒，漸嗚咽、畫角數聲殘。對閑窗畔，停燈向曉，抱影無眠。",
      "译文": "",
      "注释": "",
      "赏析": "柳永慢詞長調名篇，鋪敘羈旅秋懷。「晚秋天，一霎微雨灑庭軒」，起筆即景；「念利名、憔悴長縈絆，追往事、空慘愁顏」，宦遊之嘆與懷人之思交織。",
