      "原文": "凍雲黯淡天氣，扁舟一葉，乘興離江渚。度萬壑千岩，越溪深處。怒濤漸息，樵風乍起，更聞商旅相呼。片帆高舉，泛畫鷁、翩翩過南浦。望中酒旆閃閃，一簇煙村，數行霜樹。殘日下、漁人鳴榔歸去。敗荷零落，衰楊掩映。岸邊兩兩三三，浣紗游女，避行客、含羞笑相語。到此因念，繡閣輕拋，浪萍難駐。嘆後約叮嚀竟何據？慘離懷、空恨歲晚歸期阻。凝淚眼、杳杳神京路，斷鴻聲遠長天暮。",
      "译文": "",
