      "赏析": "寫江行羈旅。「凍雲黯淡天氣，扁舟一葉，乘興離江渚」，扁舟孤客；結句「凝淚眼、杳杳神京路，斷鴻聲遠長天暮」，思歸之情寄於天際。",
