      "标题": "玉蝴蝶",
      "上句": "",
      "下句": "",
      "原文": "望處雨收雲斷，憑闌悄悄，目送秋光。晚景蕭疏，堪動宋玉悲涼。水風輕、蘋花漸老；月露冷、梧葉飄黃。遣情傷，故人何在？煙水茫茫。難忘。文期酒會，幾孤風月，屢變星霜。海闊山遙，未知何處是瀟湘？念雙燕、難憑音信；指暮天、空識歸航。黯相望，斷鴻聲裏，立盡斜陽。",
      "译文": "",
      "注释": "",
      "赏析": "秋日懷人之作。「望處雨收雲斷，憑闌悄悄，目送秋光」，登樓望遠；「黯相望，斷鴻聲裏，立盡斜陽」，佇立之久見相思之深。",
