      "标题": "八聲甘州",
      "上句": "",
      "下句": "",
      "原文": "對瀟瀟暮雨灑江天，一番洗清秋。漸霜風淒緊，關河冷落，殘照當樓。是處紅衰翠減，苒苒物華休。惟有長江水，無語東流。不忍登高臨遠，望故鄉渺邈，歸思難收。嘆年來蹤跡，何事苦淹留？想佳人、妝樓顒望，誤幾回、天際識歸舟？爭知我、倚闌干處，正恁凝愁。",
      "译文": "",
      "注释": "",
      "赏析": "柳永羈旅名篇。「對瀟瀟暮雨灑江天，一番洗清秋」，以雨洗清秋開篇，境界蒼茫；結句「爭知我、倚闌干處，正恁凝愁」，將思歸之情凝於一處。",
