      "原文": "一葉扁舟輕帆卷，暫泊楚江南岸。孤城暮角，引胡笳怨。水茫茫，平沙雁。旋驚散。煙斂寒林簇，畫屏展，天際遙山小，黛眉淺。舊賞輕拋，到此成游宦。覺客程勞，年光晚。異鄉風物，忍蕭索，當愁眼。帝城賒，秦樓阻，旅魂亂。芳草連空闊，殘照滿，佳人無消息，斷雲遠。",
