      "原文": "登孤壘荒涼，危亭曠望，靜臨煙渚。對雌霓掛雨，雄風拂檻，微收煩暑。漸覺一葉驚秋，殘蟬噪晚，素商時序。覽景想前歡，指神京、非霧非煙深處。向此成追感，新愁易積，故人難聚。憑高盡日凝佇，贏得消魂無語。極目霽靄霏微，暝鴉零亂，蕭索江城暮。南樓畫角，又送殘陽去。",
