      "原文": "登臨送目，正故國晚秋，天氣初肅。千里澄江似練，翠峰如簇。歸帆去棹殘陽裏，背西風，酒旗斜矗。彩舟雲淡，星河鷺起，畫圖難足。念往昔、繁華競逐，嘆門外樓頭，悲恨相續。千古憑高，對此漫嗟榮辱。六朝舊事隨流水，但寒煙、芳草凝綠。至今商女，時時猶唱，《後庭》遺曲。",
