      "下句": "別館寒砧，孤城畫角，一派秋聲入寥廓。東歸燕從海上去，南來雁向沙頭落。楚臺風，庾樓月，宛如昨。無奈被些名利縛，無奈被他情擔擱，可惜風流總閑卻。當初漫留華表語，而今誤我秦樓約。夢闌時，酒醒後，思量著。",
