      "原文": "夢後樓臺高鎖，酒醒簾幕低垂。去年春恨卻來時，落花人獨立，微雨燕雙飛。記得小蘋初見，兩重心字羅衣。琵琶弦上說相思，當時明月在，曾照彩雲歸。",
