      "原文": "夢入江南煙水路，行盡江南，不與離人遇。睡裏消魂無說處，覺來惆悵消魂誤。欲盡此情書尺素，浮雁沉魚，終了無憑據。卻倚緩弦歌別緒，斷腸移破秦箏柱。",
      "译文": "",
      "注释": "",
      "赏析": "夢中尋人之作。「夢入江南煙水路，行盡江南，不與離人遇」，夢尋不遇；結句「斷腸移破秦箏柱」，借箏寫恨，哀怨深長。",
