      "下句": "醉別西樓醒不記，春夢秋雲，聚散真容易。斜月半窗還少睡，畫屏閑展吳山翠。衣上酒痕詩裏字，點點行行，總是淒涼意。紅燭自憐無好計，夜寒空替人垂淚。",
