      "原文": "醉別西樓醒不記，春夢秋雲，聚散真容易。斜月半窗還少睡，畫屏閑展吳山翠。衣上酒痕詩裏字，點點行行，總是淒涼意。紅燭自憐無好計，夜寒空替人垂淚。",
      "译文": "",
      "注释": "",
      "赏析": "離別之恨。「醉別西樓醒不記，春夢秋雲，聚散真容易」，聚散無常之嘆；「衣上酒痕詩裏字，點點行行，總是淒涼意」，舊跡處處惹愁。",
