      "原文": "彩袖殷勤捧玉鍾，當年拚卻醉顏紅。舞低楊柳樓心月，歌盡桃花扇底風。從別後，憶相逢，幾回魂夢與君同。今宵剩把銀釭照，猶恐相逢是夢中。",
      "译文": "",
      "注释": "",
      "赏析": "晏幾道名篇，追憶當年歌舞之會。「舞低楊柳樓心月，歌盡桃花扇底風」，寫盡狂歡之盛；結句「今宵剩把銀釭照，猶恐相逢是夢中」，歡會如夢，喜極而疑。",
