      "上句": "",
      "下句": "",
      "原文": "舊香殘粉似當初，人情恨不如。一春猶有數行書，秋來書更疏。衾鳳冷，枕鴛孤，愁腸待酒舒。夢魂縱有也成虛，那堪和夢無。",
      "译文": "",
      "注释": "",
      "赏析": "舊情難忘。「舊香殘粉似當初，人情恨不如」，物是而人非；結句「夢魂縱有也成虛，那堪和夢無」，連夢中相見亦不可得，悲涼至極。",
      "链接": ""
