      "上句": "綠陰春盡，飛絮繞香閣",
      "下句": "綠陰春盡，飛絮繞香閣。晚來翠眉宮樣，巧把遠山學。一寸狂心未說，已向橫波覺。畫簾遮匝，新翻曲妙，暗許閑人帶偷掐。前度書多隱語，意淺愁難答。昨夜詩有回文，韻險還慵押。都待笙歌散了，記取來時霎。不消紅蠟，閑雲歸後，月在庭花舊闌角。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
