      "标题": "六么令",
      "上句": "",
      "下句": "",
      "原文": "綠陰春盡，飛絮繞香閣。晚來翠眉宮樣，巧把遠山學。一寸狂心未說，已向橫波覺。畫簾遮匝，新翻曲妙，暗許閑人帶偷掐。前度書多隱語，意淺愁難答。昨夜詩有回文，韻險還慵押。都待笙歌散了，記取來時霎。不消紅蠟，閑雲歸後，月在庭花舊闌角。",
      "译文": "",
      "注释": "",
      "赏析": "寫閨中春情。「一寸狂心未說，已向橫波覺」，眉目傳情；結句「閑雲歸後，月在庭花舊闌角」，以景收束，情韻悠長。",
