      "下句": "街南綠樹春饒絮，雪滿游春路。樹頭花艷雜嬌雲，樹底人家朱戶。北樓閑上，疏簾高卷，直見街南樹。闌干倚盡猶慵去，幾度黃昏雨。晚春盤馬踏青苔，曾傍綠陰深駐。落花猶在，香屏空掩，人面知何處？",
