      "原文": "曲闌干外天如水，昨夜還曾倚。初將明月比佳期，長向月圓時候、望人歸。羅衣著破前香在，舊意誰教改。一春離恨懶調弦。猶有兩行閑淚、寶箏前。",
      "译文": "",
      "注释": "",
      "赏析": "倚欄望月懷人。「曲闌干外天如水，昨夜還曾倚」，天如水，倚欄獨望；「一春離恨懶調弦。猶有兩行閑淚、寶箏前」，離恨難遣，淚灑箏前。",
