      "上句": "紅葉黃花秋意晚，千里念行客",
      "下句": "紅葉黃花秋意晚，千里念行客。飛雲過盡，歸鴻無信，何處寄書得？淚彈不盡臨窗滴，就硯旋研墨。漸寫到別來，此情深處，紅箋為無色。",
