      "标题": "水龍吟",
      "上句": "",
      "下句": "",
      "原文": "似花還似非花，也無人惜從教墜。拋家傍路，思量卻是，無情有思。縈損柔腸，困酣嬌眼，欲開還閉。夢隨風萬里，尋郎去處，又還被鶯呼起。不恨此花飛盡，恨西園、落紅難綴。曉來雨過，遺蹤何在？一池萍碎。春色三分，二分塵土，一分流水。細看來不是楊花，點點是離人淚。",
      "译文": "",
      "注释": "",
      "赏析": "次韻章質夫楊花詞。「似花還似非花，也無人惜從教墜」，起筆便見高格；結句「細看來不是楊花，點點是離人淚」，物我交融，神韻天成。",
