      "上句": "",
      "下句": "",
      "原文": "明月如霜，好風如水，清景無限。曲港跳魚，圓荷瀉露，寂寞無人見。紞如三鼓，鏗然一葉，黯黯夢雲驚斷。夜茫茫、重尋無處，覺來小園行遍。天涯倦客，山中歸路，望斷故園心眼。燕子樓空，佳人何在？空鎖樓中燕。古今如夢，何曾夢覺，但有舊歡新怨。異時對、黃樓夜景，為余浩嘆。",
      "译文": "",
      "注释": "",
      "赏析": "彭城燕子樓懷古之作。「明月如霜，好風如水，清景無限」，清景如畫；「燕子樓空，佳人何在？空鎖樓中燕」，今昔盛衰之嘆深沉。",
