      "标题": "洞仙歌",
      "上句": "",
      "下句": "",
      "原文": "冰肌玉骨，自清涼無汗。水殿風來暗香滿。繡簾開、一點明月窺人，人未寢，欹枕釵橫鬢亂。起來攜素手，庭戶無聲，時見疏星渡河漢。試問夜如何？夜已三更，金波淡、玉繩低轉。但屈指、西風幾時來，又不道流年、暗中偷換。",
      "译文": "",
      "注释": "",
      "赏析": "寫蜀主花蕊夫人夏夜情事。「冰肌玉骨，自清涼無汗」，美人風神自見；結句「但屈指、西風幾時來，又不道流年、暗中偷換」，流年暗換之慨寄於無形。",
