      "标题": "卜算子",
      "上句": "",
      "下句": "",
      "原文": "缺月掛疏桐，漏斷人初靜。誰見幽人獨往來，縹緲孤鴻影。驚起卻回頭，有恨無人省。揀盡寒枝不肯棲，寂寞沙洲冷。",
      "译文": "",
      "注释": "",
      "赏析": "黃州定惠院寓居之作，詠孤鴻自況。「缺月掛疏桐，漏斷人初靜」，幽獨之境；「揀盡寒枝不肯棲，寂寞沙洲冷」，孤高自守，正是東坡人格寫照。",
