      "上句": "三年枕上吳中路，遣黃犬、隨君去",
      "下句": "三年枕上吳中路，遣黃犬、隨君去。若到松江呼小渡，莫驚鴛鷺，四橋盡是、老子經行處。輞川圖上看春暮，常記高人右丞句。作個歸期天定許，春衫猶是，小蠻針線，曾濕西湖雨。",
