      "上句": "",
      "下句": "",
      "原文": "莫聽穿林打葉聲，何妨吟嘯且徐行。竹杖芒鞋輕勝馬，誰怕？一蓑煙雨任平生。料峭春風吹酒醒，微冷，山頭斜照卻相迎。回首向來蕭瑟處，歸去，也無風雨也無晴。",
      "译文": "",
      "注释": "",
      "赏析": "沙湖道中遇雨之作。「莫聽穿林打葉聲，何妨吟嘯且徐行」，於風雨中見曠達；結句「回首向來蕭瑟處，歸去，也無風雨也無晴」，參透得失榮辱，境界超然。",
