    "fields": {
      "篇目": "宋词三百首 · 賀新郎 · 蘇軾 · 賀新郎",
      "标题": "賀新郎",
      "上句": "乳燕飛華屋，悄無人、槐陰轉午，晚涼新浴",
      "下句": "乳燕飛華屋，悄無人、槐陰轉午，晚涼新浴。手弄生綃白團扇，扇手一時似玉。漸困倚、孤眠清熟，簾外誰來推繡戶？枉教人、夢斷《瑤臺曲》，又卻是、風敲竹。石榴半吐紅巾蹙，待浮花、浪蕊都盡，伴君幽獨。穠艷一枝細看取，芳意千重似束。又恐被西風驚綠，若待得君來向此，花前對酒不忍觸。共粉淚、兩簌簌。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
