      "上句": "",
      "下句": "",
      "原文": "梅英疏淡，冰澌溶泄，東風暗換年華。金谷俊游，銅駝巷陌，新晴細履平沙。長記誤隨車，正絮翻蝶舞，芳思交加。柳下桃蹊，亂分春色到人家。西園夜飲鳴笳，有華燈礙月，飛蓋妨花。蘭苑未空，行人漸老，重來是事堪嗟。煙暝酒旗斜。但倚樓極目，時見棲鴉。無奈歸心。暗隨流水到天涯。",
      "译文": "",
      "注释": "",
      "赏析": "春遊懷舊之作。「梅英疏淡，冰澌溶泄，東風暗換年華」，暗換年華點題；結句「無奈歸心。暗隨流水到天涯」，歸思隨流水而遠。",
