      "标题": "八六子",
      "上句": "",
      "下句": "",
      "原文": "倚危亭、恨如芳草，萋萋劃盡還生。念柳外青驄別後，水邊紅袂分時，愴然暗驚。無端天與娉婷，夜月一簾幽夢，春風十里柔情。怎奈向、歡娛漸隨流水，素弦聲斷，翠綃香減。那堪片片飛花弄晚，濛濛殘雨籠晴。正銷凝，黃鸝又啼數聲。",
      "译文": "",
      "注释": "",
      "赏析": "寫離愁。「倚危亭、恨如芳草，萋萋劃盡還生」，以芳草喻恨，割盡還生；「那堪片片飛花弄晚，濛濛殘雨籠晴」，暮春景物助愁。",
