    "fields": {
      "篇目": "宋词三百首 · 滿庭芳 · 秦觀 · 滿庭芳",
      "标题": "滿庭芳",
      "上句": "山抹微雲，天黏衰草，畫角聲斷譙門",
      "下句": "山抹微雲，天黏衰草，畫角聲斷譙門。暫停征棹，聊共引離樽。多少蓬萊舊事，空回首、煙靄紛紛。斜陽外，寒鴉萬點，流水繞孤村。銷魂，當此際，香囊暗解，羅帶輕分。漫贏得青樓，薄幸名存。此去何時見也？襟袖上、空惹啼痕。傷情處，高城望斷，燈火已黃昏。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
