      "上句": "",
      "下句": "",
      "原文": "曉色雲開，春隨人意，驟雨才過還晴。古臺芳榭，飛燕蹴紅英。舞困榆錢自落，秋千外、綠水橋平。東風裏，朱門映柳，低按小秦箏。多情，行樂處，珠鈿翠蓋，玉轡紅纓。漸酒空金榼，花困蓬瀛。豆蔻梢頭舊恨，十年夢，屈指堪驚。憑闌久，疏煙淡日，寂寞下蕪城。",
      "译文": "",
      "注释": "",
      "赏析": "春日懷舊。「曉色雲開，春隨人意，驟雨才過還晴」，春景明麗；結句「憑闌久，疏煙淡日，寂寞下蕪城」，熱鬧歸於寂寞。",
