      "上句": "天涯舊恨，獨自淒涼人不問",
      "下句": "天涯舊恨，獨自淒涼人不問。欲見回腸，斷盡金爐小篆香。黛蛾長斂，任是春風吹不展。困倚危樓，過盡飛鴻字字愁。",
