      "标题": "減字木蘭花",
      "上句": "",
      "下句": "",
      "原文": "天涯舊恨，獨自淒涼人不問。欲見回腸，斷盡金爐小篆香。黛蛾長斂，任是春風吹不展。困倚危樓，過盡飛鴻字字愁。",
      "译文": "",
      "注释": "",
      "赏析": "寫天涯舊恨。「天涯舊恨，獨自淒涼人不問」，起筆直抒；「困倚危樓，過盡飛鴻字字愁」，以雁字寫愁，字字含情。",
