      "篇目": "宋词三百首 · 綠頭鴨 · 晁元禮 · 綠頭鴨",
      "标题": "綠頭鴨",
      "上句": "晚雲收，淡天一片琉璃",
      "下句": "晚雲收，淡天一片琉璃。爛銀盤、來從海底，皓色千里澄輝。瑩無塵、素娥淡佇，靜可數、丹桂參差。玉露初零，金風未凜，一年無似此佳時。露坐久、疏瑩時度，烏鵲正南飛。瑤臺冷，欄干憑暖，欲下遲遲。念佳人、音塵別後，對此應解相思。最關情、漏聲正永，暗斷腸、花影偷移。料得來宵，清光未減，陰晴天氣又爭知。共凝戀、如今別後，還是隔年期。人強健，清樽素影，長願相隨。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
