      "原文": "欲減羅衣寒未去，不卷珠簾，人在深深處。紅杏枝頭花幾許？啼痕止恨清明雨。盡日沉煙香一縷，宿酒醒遲，惱破春情緒。飛燕又將歸信誤，小屏風上西江路。",
      "译文": "",
      "注释": "",
      "赏析": "閨中春怨。「欲減羅衣寒未去，不卷珠簾，人在深深處」，深閨寂寥；「飛燕又將歸信誤，小屏風上西江路」，燕誤歸信，愁緒愈深。",
