      "上句": "卷絮風頭寒欲盡，墜粉飄香，日日紅成陣",
      "下句": "卷絮風頭寒欲盡，墜粉飄香，日日紅成陣。新酒又添殘酒困，今春不減前春恨。蝶去鶯飛無處問，隔水高樓，望斷雙魚信。惱亂橫波秋一寸，斜陽只與黃昏近。",
