      "标题": "清平樂",
      "上句": "",
      "下句": "",
      "原文": "春風依舊，著意隨堤柳。搓得鵝兒黃欲就，天氣清明時候。去年紫陌青門，今霄雨魄雲魂。斷送一生憔悴，只消幾個黃昏？",
      "译文": "",
      "注释": "",
      "赏析": "春日懷人。「春風依舊，著意隨堤柳」，春風如昨；結句「斷送一生憔悴，只消幾個黃昏」，以黃昏寫憔悴，沉痛入骨。",
