      "上句": "青煙冪處，碧海飛金鏡",
      "下句": "青煙冪處，碧海飛金鏡。永夜閑階臥桂影。露涼時，零亂多少寒螿，神京遠，惟有藍橋路近。水晶簾不下，雲母屏開，冷浸佳人淡脂粉。待都將許多明，付與金樽，投曉共流霞傾盡。更攜取胡床上南樓，看玉做人間，素秋千頃。",
      "原文": "",
      "译文": "",
      "注释": "",
