      "上句": "",
      "下句": "",
      "原文": "青煙冪處，碧海飛金鏡。永夜閑階臥桂影。露涼時，零亂多少寒螿，神京遠，惟有藍橋路近。水晶簾不下，雲母屏開，冷浸佳人淡脂粉。待都將許多明，付與金樽，投曉共流霞傾盡。更攜取胡床上南樓，看玉做人間，素秋千頃。",
      "译文": "",
      "注释": "",
      "赏析": "泗州中秋作。「青煙冪處，碧海飛金鏡」，寫中秋月出；結句「看玉做人間，素秋千頃」，清景無限，胸懷開闊。",
