      "原文": "雪雲散盡，放曉晴庭院。楊柳于人便青眼。更風流多處，一點梅心，相映遠，約略顰輕笑淺。一年春好處，不在濃芳，小艷疏香最嬌軟。到清明時候，百紫千紅花正亂，已失春風一半。早占取、韶光共追游，但莫管春寒，醉紅自暖。",
      "译文": "",
      "注释": "",
      "赏析": "早春之作。「雪雲散盡，放曉晴庭院」，雪霽春來；「一年春好處，不在濃芳，小艷疏香最嬌軟」，審美獨到，見早春之韻。",
