      "标题": "青門飲",
      "上句": "胡馬嘶風，漢旗翻雪，彤雲又吐，一竿殘照",
      "下句": "胡馬嘶風，漢旗翻雪，彤雲又吐，一竿殘照。古木連空，亂山無數，行盡暮沙衰草。星斗橫幽館，夜無眠燈花空老。霧濃香鴨，冰凝淚燭，霜天難曉。長記小妝才了，一杯未盡，離懷多少。醉裏秋波，夢中朝雨，都是醒時煩惱，料有牽情處，忍思量耳邊曾道。甚時躍馬歸來，認得迎門輕笑。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
