      "上句": "殘寒消盡，疏雨過、清明後",
      "下句": "殘寒消盡，疏雨過、清明後。花徑斂餘紅，風沼縈新皺。乳燕穿庭戶，飛絮沾襟袖。正佳時仍晚晝，著人滋味，真箇濃如酒。頻移帶眼，空只恁厭厭瘦。不見又思量，見了還依舊。為問頻相見，何似長相守？天不老，人未偶，且將此恨，分付庭前柳。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
