      "标题": "卜算子",
      "上句": "",
      "下句": "",
      "原文": "我住長江頭，君住長江尾；日日思君不見君，共飲長江水。此水幾時休？此恨何時已？只願君心似我心，定不負相思意。",
      "译文": "",
      "注释": "",
      "赏析": "李之儀名篇。「我住長江頭，君住長江尾；日日思君不見君，共飲長江水」，以江水貫穿全篇，天然妙絕；結句「只願君心似我心，定不負相思意」，痴情而堅定。",
