      "标题": "瑞龍吟",
      "上句": "章臺路，還見褪粉梅梢，試花桃樹",
      "下句": "章臺路，還見褪粉梅梢，試花桃樹。愔愔坊陌人家，定巢燕子，歸來舊處。黯凝佇，因念個人痴小，乍窺門戶。侵晨淺約宮黃，障風映袖，盈盈笑語。前度劉郎重到，訪鄰尋里，同時歌舞，惟有舊家秋娘，聲價如故。吟箋賦筆，猶記燕臺句。知誰伴，名園露飲，東城閑步？事與孤鴻去，探春盡是，傷離意緒。官柳低金縷，歸騎晚、纖纖池塘飛雨。斷腸院落，一簾風絮。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
