      "标题": "風流子",
      "上句": "新綠小池塘，風簾動、碎影舞斜陽",
      "下句": "新綠小池塘，風簾動、碎影舞斜陽。羨金屋去來，舊時巢燕；土花繚繞，前度莓牆。繡閣裏、鳳幃深幾許？聽得理絲簧。欲說又休，慮乖芳信；未歌先噎，愁近清觴。遙知新妝了，開朱戶、應自待月西廂。最苦夢魂，今宵不到伊行。問甚時說與，佳音密耗，寄將秦鏡，偷換韓香？天便教人，霎時廝見何妨！",
