      "原文": "暗柳啼鴉，單衣佇立，小簾朱戶。桐花半畝，靜鎖一庭愁雨。灑空階、夜闌未休，故人剪燭西窗語。似楚江暝宿，風燈零亂，少年羈旅。遲暮，嬉游處。正店舍無煙，禁城百五。旗亭喚酒，付與高陽儔侶。想東園、桃李自春，小唇秀靨今在否？到歸時、定有殘英，待客攜樽俎。",
      "译文": "",
