      "上句": "粉牆低，梅花照眼，依然舊風味",
      "下句": "粉牆低，梅花照眼，依然舊風味。露痕輕綴，疑淨洗鉛華，無限佳麗。去年勝賞曾孤倚，冰盤同燕喜。更可惜、雪中高樹，香篝熏素被。今年對花最匆匆，相逢似有恨，依依愁悴。吟望久，青苔上，旋看飛墜。相將見、翠丸薦酒，人正在、空江煙浪裏。但夢想、一枝瀟灑，黃昏斜照水。",
