      "上句": "風消焰蠟，露浥紅蓮，花市光相射",
      "下句": "風消焰蠟，露浥紅蓮，花市光相射。桂華流瓦，纖雲散、耿耿素娥欲下。衣裳淡雅，看楚女纖腰一把。簫鼓喧、人影參差，滿路飄香麝。因念都城放夜，望千門如晝，嬉笑游冶。鈿車羅帕，相逢處、自有暗塵隨馬。年光是也，惟只見、舊情衰謝。清漏移、飛蓋歸來，從舞休歌罷。",
      "原文": "",
      "译文": "",
      "注释": "",
