      "原文": "月皎驚烏棲不定，更漏將闌，轣轆牽金井。喚起兩眸清炯炯，淚花落枕紅綿泠。執手霜風吹鬢影，去意徊徨，別語愁難聽。樓上闌干橫斗柄，露寒人遠雞相應。",
