      "原文": "夜色催更，清塵收露，小曲幽坊月暗。竹檻燈窗，識秋娘庭院。笑相遇，似覺瓊枝玉樹相倚，暖日明霞光爛。水盼蘭情，總平生稀見。畫圖中，舊識春風面，誰知道、自到瑤臺畔。眷戀雨潤雲溫，苦驚風吹散。念荒寒、寄宿無人館，重門閉，敗壁秋蟲嘆。怎奈向、一縷相思，隔溪山不斷。",
      "译文": "",
      "注释": "",
      "赏析": "寫夜會之憶。「夜色催更，清塵收露，小曲幽坊月暗」，幽坊月暗；結句「怎奈向、一縷相思，隔溪山不斷」，相思隔山不斷，深情綿邈。",
