      "上句": "上馬人扶殘醉，曉風吹未醒",
      "下句": "上馬人扶殘醉，曉風吹未醒。映水曲、翠瓦朱檐，垂楊裏、乍見津亭。當時曾題敗壁，蛛絲罩、淡墨苔暈青。念去來、歲月如流，徘徊久、嘆息愁思盈。去去倦尋路程，江陵舊事，何曾再問楊瓊。舊曲淒清，斂愁黛、與誰聽？樽前故人如在，想念我、最關情。何須渭城，歌聲未盡處，先淚零。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
