      "上句": "隋堤路，漸日晚、密靄生煙樹",
      "下句": "隋堤路，漸日晚、密靄生煙樹。陰陰淡月籠沙，還宿河橋深處。無情畫舸，都不管、煙波隔前浦。等行人、醉擁重衾，載將離恨歸去。因思舊客京華，長偎傍疏林，小檻歡聚。冶葉倡條俱相識，仍慣見珠歌翠舞。如今向、漁村水驛，夜如歲、焚香獨自語。有何人、念我無聊。夢魂凝想鴛侶。",
