      "上句": "佳麗地，南朝盛事誰記",
      "下句": "佳麗地，南朝盛事誰記？山圍故國繞清江，髻鬟對起。怒濤寂寞打孤城，風檣遙度天際。斷崖樹，猶倒倚，莫愁艇子誰繫？空餘舊跡鬱蒼蒼，霧沈半壘。夜深月過女牆來，傷心東望淮水。酒旗戲鼓甚處市？想依稀王謝鄰里。燕子不知何世，入尋常巷陌人家，相對如說興亡，斜陽裏。",
