      "原文": "悄郊原帶郭，行路永、客去車塵漠漠。斜陽映山落，斂餘紅猶戀，孤城欄角。凌波步弱，過短亭、何用素約。有流鶯勸我，重解繡鞍，緩引春酌。不記歸時早暮，上馬誰扶，醒眠朱閣。驚飆動幕，扶殘醉、繞紅藥。嘆西園已是，花深無地，東風何事又惡？任流光過卻，猶喜洞天自樂。",
      "译文": "",
      "注释": "",
      "赏析": "送客之作。「悄郊原帶郭，行路永、客去車塵漠漠」，客去塵遠；「任流光過卻，猶喜洞天自樂」，於悵惘中見自解曠達。",
