      "标题": "夜游宮",
      "上句": "",
      "下句": "",
      "原文": "葉下斜陽照水，卷輕浪、沉沉千里。橋上酸風射眸子，立多時，看黃昏，燈火市。古屋寒窗底，聽幾片、井桐飛墜。不戀單衾再三起，有誰知，為蕭娘，書一紙？",
      "译文": "",
      "注释": "",
      "赏析": "秋日閨思。「葉下斜陽照水，卷輕浪、沉沉千里」，斜陽照水；結句「有誰知，為蕭娘，書一紙」，心事無人知，惟寄一紙書。",
