      "下句": "凌波不過橫塘路，但目送、芳塵去。錦瑟華年誰與度？月橋花院，瑣窗朱戶，只有春知處。飛雲冉冉蘅皋暮，彩筆新題斷腸句。試問閑愁都幾許？一川煙草，滿城風絮，梅子黃時雨。",
