      "上句": "蘭芷滿汀洲，游絲橫路",
      "下句": "蘭芷滿汀洲，游絲橫路。羅襪塵生步，迎顧，整鬟顰黛，脈脈兩情難語。細風吹柳絮、人南渡。回首舊游，山無重數。花底深朱戶，何處？半黃梅子，向晚一簾疏雨。斷魂分付與、春將去。",
