      "上句": "淡妝多態，更的的、頻回眄睞",
      "下句": "淡妝多態，更的的、頻回眄睞。便認得琴心先許，欲綰合歡雙帶。記畫堂、風月逢迎，輕顰淺笑嬌無奈。向睡鴨爐邊，翔鴛屏裏，羞把香羅暗解。自過了，燒燈後，都不見，踏青挑菜。幾回憑雙燕，丁寧深意，往來卻恨重簾礙。約何時再，正春濃酒困，人閑晝永無聊賴。厭厭睡起，猶有花梢日在。",
      "原文": "",
      "译文": "",
      "注释": "",
