      "原文": "樓角初消一縷霞，淡黃楊柳暗棲鴉，玉人和月摘梅花。笑捻粉香歸洞戶，更垂簾幕護窗紗，東風寒似夜來些。",
      "译文": "",
      "注释": "",
      "赏析": "寫玉人月下摘梅。「樓角初消一縷霞，淡黃楊柳暗棲鴉，玉人和月摘梅花」，一幅絕美的月夜圖；結句「東風寒似夜來些」，清寒中情韻悠遠。",
