      "原文": "幾許傷春春復暮，楊柳清陰，偏礙游絲度。天際小山桃葉步，白蘋花滿湔裙處。竟日微吟長短句，簾影燈昏，心寄胡琴語。數點雨聲風約住，朦朧淡月雲來去。",
      "译文": "",
      "注释": "",
      "赏析": "傷春懷人之作。「幾許傷春春復暮，楊柳清陰，偏礙游絲度」，春暮景致；結句「數點雨聲風約住，朦朧淡月雲來去」，雨聲月影，清空如畫。",
