      "原文": "煙絡橫林，山沉遠照，迤邐黃昏鐘鼓。燭映簾櫳，蛩催機杼，共苦清秋風露。不眠思婦，齊應和、幾聲砧杵。驚動天涯倦宦，駸駸歲華行暮。當年酒狂自負，謂東君、以春相付。流浪征驂北道，客檣南浦，幽恨無人晤語。賴明月，曾知舊游處，好伴雲來，還將夢去。",
      "译文": "",
