      "原文": "厭鶯聲到枕，花氣動簾，醉魂愁夢相半。被惜餘熏，帶驚剩眼，幾許傷春春晚。淚竹痕鮮，佩蘭香老，湘天濃暖。記小江風月佳時，屢約非煙游伴。須信鸞弦易斷，奈雲和再鼓，曲終人遠。認羅襪無蹤，舊處弄波清淺。青翰棹檥，白蘋洲畔，盡目臨皋飛觀。不解寄、一字相思，幸有歸來雙燕。",
      "译文": "",
