      "标题": "綠頭鴨",
      "上句": "",
      "下句": "",
      "原文": "玉人家，畫樓珠箔臨津。托微風彩簫流怨，斷腸馬上曾聞。宴堂開、艷妝叢裏，調琴思、認歌顰。麝蠟煙濃，玉蓮漏短，更衣不待酒初醺。繡屏掩、枕鴛相就，香氣漸暾暾。回廊影、疏鐘淡月，幾許消魂？翠釵分、銀箋封淚，舞鞋從此生塵。任蘭舟、載將離恨，轉南浦、背西曛。記取明年，薔薇謝後，佳期應未誤行雲。鳳城遠、楚梅香嫩，先寄一枝春。青門外，只憑芳草，尋訪郎君。",
      "译文": "",
      "注释": "",
      "赏析": "寫玉人臨津之憶。「玉人家，畫樓珠箔臨津」，美人樓居；結句「青門外，只憑芳草，尋訪郎君」，芳草尋人，情韻悠長。",
