    "fields": {
      "篇目": "宋词三百首 · 賀新郎 · 葉夢得 · 賀新郎",
      "标题": "賀新郎",
      "上句": "睡起流鶯語，掩蒼苔，房櫳向晚，亂紅無數",
      "下句": "睡起流鶯語，掩蒼苔，房櫳向晚，亂紅無數。吹盡殘花無人見，惟有垂楊自舞。漸暖靄、初回輕暑，寶扇重尋明月影，暗塵侵、上有乘鸞女。驚舊恨，遽如許。江南夢斷橫江渚，浪黏天、葡萄漲綠，半空煙雨。無限樓前滄波意，誰采蘋花寄取？但悵望、蘭舟容與，萬里雲帆何時到？送孤鴻、目斷千山阻。誰為我，唱《金縷》。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
