      "原文": "落花已作風前舞，又送黃昏雨。曉來庭院半殘紅，惟有游絲千丈罥晴空。殷勤花下同攜手，更盡杯中酒。美人不用斂蛾眉，我亦多情無奈酒闌時。",
      "译文": "",
