    "fields": {
      "篇目": "宋词三百首 · 喜遷鶯 · 劉一止 · 喜遷鶯",
      "标题": "喜遷鶯",
      "上句": "曉光催角，聽宿鳥未驚，鄰雞先覺",
      "下句": "曉光催角，聽宿鳥未驚，鄰雞先覺。迤邐煙村，馬嘶人起，殘月尚穿林薄。淚痕帶霜微凝，酒力沖寒猶弱。嘆倦客，悄不禁重染，風塵京洛。追念人別後，心事萬重，難覓孤鴻托。翠幌嬌深，曲屏香暖，爭念歲華飄泊。怨月恨花煩惱，不是不曾經著。者情味、望一成消減，新來還惡。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
