      "上句": "高詠《楚詞》酬午日，天涯節序匆匆",
      "下句": "高詠《楚詞》酬午日，天涯節序匆匆。榴花不似舞裙紅，無人知此意，歌罷滿簾風。萬事一身傷老矣，戎葵凝笑牆東。酒杯深淺去年同，試澆橋下水，今夕到湘中。",
