      "下句": "憶昔午橋橋上飲，坐中多是豪英。長溝流月去無聲，杏花疏影裏，吹笛到天明。二十餘年如一夢，此身雖在堪驚。閑登小閣看新晴，古今多少事，漁唱起三更。",
