      "标题": "蘇武慢",
      "上句": "",
      "下句": "",
      "原文": "雁落平沙，煙籠寒水，古壘鳴笳聲斷。青山隱隱，敗葉蕭蕭，天際暝鴉零亂。樓上黃昏，片帆千里歸程，年華將晚。望碧雲空暮，佳人何處，夢魂俱遠。憶舊游、邃館朱扉，小園香徑，尚想桃花人面。書盈錦軸，恨滿金徽，難寫寸心幽怨。兩地離愁，一樽芳酒淒涼，危闌倚遍。盡遲留、憑仗西風，吹乾淚眼。",
      "译文": "",
      "注释": "",
      "赏析": "羈旅秋思。「雁落平沙，煙籠寒水，古壘鳴笳聲斷」，秋江暮景；「盡遲留、憑仗西風，吹乾淚眼」，西風吹淚，悲涼無限。",
