      "原文": "數聲鶗鴃，可憐又是、春歸時節。滿院東風，海棠鋪繡，梨花飄雪。丁香露泣殘枝，算未比、愁腸寸結，自是休文，多情多感，不干風月。",
      "译文": "",
      "注释": "",
      "赏析": "傷春之作。「數聲鶗鴃，可憐又是、春歸時節」，鶗鴃催春歸；「丁香露泣殘枝，算未比、愁腸寸結」，以丁香結比愁腸，工巧深婉。",
