      "上句": "一點殘釭欲盡時，乍涼秋氣滿屏幃",
      "下句": "一點殘釭欲盡時，乍涼秋氣滿屏幃。梧桐葉上三更雨，葉葉聲聲是別離。調寶瑟，撥金猊，那時同唱《鷓鴣詞》。如今風雨西樓夜，不聽清歌也淚垂。",
