      "篇目": "宋词三百首 · 鷓鴣天 · 周紫芝 · 鷓鴣天",
      "标题": "鷓鴣天",
      "上句": "",
      "下句": "",
      "原文": "一點殘釭欲盡時，乍涼秋氣滿屏幃。梧桐葉上三更雨，葉葉聲聲是別離。調寶瑟，撥金猊，那時同唱《鷓鴣詞》。如今風雨西樓夜，不聽清歌也淚垂。",
      "译文": "",
      "注释": "",
      "赏析": "秋夜懷人之作。「一點殘釭欲盡時，乍涼秋氣滿屏幃」，殘燈秋夜；結句「如今風雨西樓夜，不聽清歌也淚垂」，觸景傷情，淚自暗垂。",
