      "标题": "憶王孫",
      "上句": "",
      "下句": "",
      "原文": "萋萋芳草憶王孫，柳外樓高空斷魂，杜宇聲聲不忍聞。欲黃昏，雨打梨花深閉門。",
      "译文": "",
      "注释": "",
      "赏析": "閨怨之作。「萋萋芳草憶王孫，柳外樓高空斷魂」，芳草憶人；結句「欲黃昏，雨打梨花深閉門」，雨打梨花，深閉重門，愁思愈深。",
