      "原文": "悶來彈鵲，又攪碎、一簾花影。漫試著春衫，還思纖手，燻徹金猊燼冷。動是愁端如何向？但怪得新來多病。嗟舊日沈腰，如今潘鬢，怎堪臨鏡？重省，別時淚濕，羅衣猶凝，料為我厭厭，日高慵起，長托春酲未醒。雁足不來，馬蹄難駐，門掩一庭芳景。空佇立，盡日闌干，倚遍晝長人靜。",
      "译文": "",
      "注释": "",
      "赏析": "寫愁病之思。「悶來彈鵲，又攪碎、一簾花影」，彈鵲驚影；結句「空佇立，盡日闌干，倚遍晝長人靜」，日長人靜，愁緒難遣。",
