      "原文": "玉臺掛秋月，鉛素淺、梅花傅香雪。冰姿潔，金蓮襯、小小凌波羅襪。雨初歇，樓外孤鴻聲漸遠，遠山外、行人音信絕。此恨對語猶難，那堪更寄書說。教人紅消翠減，覺衣寬金縷，都為輕別。太情切。消魂處、畫角黃昏時節。聲嗚咽。落盡庭花春去也，銀蟾迥、無情圓又缺。恨伊不似餘香，惹鴛鴦結。",
      "译文": "",
      "注释": "",
      "赏析": "寫別後相思。「玉臺掛秋月，鉛素淺、梅花傅香雪」，秋月照人；「恨伊不似餘香，惹鴛鴦結」，以餘香喻情，含蓄綿邈。",
