      "原文": "洗妝真態，不作鉛華御。竹外一枝斜，想佳人天寒日暮。黃昏院落，無處著清香，風細細，雪垂垂，何況江頭路。月邊疏影，夢到消魂處。結子欲黃時，又須作廉纖細雨。孤芳一世，供斷有情愁，消瘦損，東陽也，試問花知否？",
      "译文": "",
