      "标题": "燭影搖紅",
      "上句": "靄靄春空，畫樓森聳凌雲渚",
      "下句": "靄靄春空，畫樓森聳凌雲渚。紫薇登覽最關情，絕妙誇能賦。惆悵相思遲暮，記當日、朱闌共語。塞鴻難問，岸柳何窮，別愁紛絮。催促年光，舊來流水知何處？斷腸何必更殘陽，極目傷平楚。晚霽波聲帶雨，悄無人舟橫野渡。數峰江上，芳草天涯，參差煙樹。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
