      "原文": "風悲畫角，聽《單于》、三弄落譙門。投宿駸駸征騎，飛雪滿孤村。酒市漸闌燈火，正敲窗、亂葉舞紛紛。送數聲驚雁，乍離煙水，嘹唳度寒雲。好在半朧淡月，到如今、無處不消魂。故國梅花歸夢，愁損綠羅裙。為問暗香閑艷，也相思、萬點付啼痕。算翠屏應是，兩眉餘恨倚黃昏。",
      "译文": "",
