      "译文": "",
      "注释": "",
      "赏析": "岳飛壯懷名篇。「怒髮衝冠，憑闌處、瀟瀟雨歇」，忠憤填膺；「壯志饑餐胡虜肉，笑談渴飲匈奴血」，豪情激越；結句「待從頭、收拾舊山河，朝天闕」，氣壯山河。",
