      "上句": "雙闕中天，鳳樓十二春寒淺",
      "下句": "雙闕中天，鳳樓十二春寒淺。去年元夜奉宸游，曾侍瑤池宴。玉殿珠簾盡卷，擁群仙、蓬壺閬苑。五雲深處，萬燭光中，揭天絲管。馳隙流年，恍如一瞬星霜換。今宵誰念泣孤臣，回首長安遠。可是塵緣未斷，漫惆悵、華胥夢短。滿懷幽恨，數點寒燈，幾聲歸雁。",
