      "上句": "夜來風雨匆匆，故園定是花無幾",
      "下句": "夜來風雨匆匆，故園定是花無幾。愁多怨極，等閑孤負，一年芳意。柳困桃慵，杏青梅小，對人容易。算好春長在，好花長見，原只是、人憔悴。回首池南舊事，恨星星、不堪重記。如今但有，看花老眼，傷時清淚。不怕逢花瘦，只愁怕、老來風味。待繁紅亂處，留雲借月，也須拚醉。",
      "原文": "",
      "译文": "",
      "注释": "",
