      "上句": "長淮望斷，關塞莽然平",
      "下句": "長淮望斷，關塞莽然平。征塵暗，霜風勁，悄邊聲。黯消凝，追想當年事，殆天數，非人力，洙泗上，弦歌地，亦膻腥。隔水氈鄉，落日牛羊下，區脫縱橫。看名王宵獵，騎火一川明，笳鼓悲鳴，遣人驚。念腰間箭，匣中劍，空埃蠹，竟何成！時易失，心徒壯，歲將零，渺神京。干羽方懷遠，靜烽燧，且休兵。冠蓋使，紛馳騖，若為情。聞道中原遺老，常南望，翠葆霓旌。使行人到此，忠憤氣填膺，有淚如傾。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
