      "篇目": "宋词三百首 · 六州歌頭 · 張孝祥 · 六州歌頭",
      "标题": "六州歌頭",
      "上句": "",
      "下句": "",
      "原文": "長淮望斷，關塞莽然平。征塵暗，霜風勁，悄邊聲。黯消凝，追想當年事，殆天數，非人力，洙泗上，弦歌地，亦膻腥。隔水氈鄉，落日牛羊下，區脫縱橫。看名王宵獵，騎火一川明，笳鼓悲鳴，遣人驚。念腰間箭，匣中劍，空埃蠹，竟何成！時易失，心徒壯，歲將零，渺神京。干羽方懷遠，靜烽燧，且休兵。冠蓋使，紛馳騖，若為情。聞道中原遺老，常南望，翠葆霓旌。使行人到此，忠憤氣填膺，有淚如傾。",
      "译文": "",
      "注释": "",
      "赏析": "張孝祥忠憤名篇。「長淮望斷，關塞莽然平」，望斷中原；「使行人到此，忠憤氣填膺，有淚如傾」，忠憤填膺，聲情激越，為愛國詞絕唱。",
