      "标题": "念奴嬌",
      "上句": "洞庭青草，近中秋、更無一點風色",
      "下句": "洞庭青草，近中秋、更無一點風色。玉界瓊田三萬頃，著我扁舟一葉。素月分輝，銀河共影，表裏俱澄澈。怡然心會，妙處難與君說。應念嶺海經年，孤光自照，肝膽皆冰雪。短髮蕭騷襟袖冷，穩泛滄浪空闊。盡挹西江，細斟北斗，萬象為賓客。扣舷獨嘯，不知今夕何夕。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
