      "标题": "六州歌頭",
      "上句": "東風著意，先上小桃枝",
      "下句": "東風著意，先上小桃枝。紅粉膩，嬌如醉，倚朱扉。記年時，隱映新妝面，臨水岸，春將半，雲日暖，斜橋轉，夾城西。草軟莎平。跋馬垂楊渡，玉勒爭嘶。認蛾眉，凝笑臉，薄拂燕脂，繡戶曾窺，恨依依。共攜手處，香如霧，紅隨步，怨春遲。消瘦損，憑誰問？只花知，淚空垂。舊日堂前燕，和煙雨，又雙飛。人自老，春長好，夢佳期。前度劉郎，幾許風流地，花也應悲。但茫茫暮靄，目斷武陵溪，往事難追。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
