      "上句": "郊原初過雨，見數葉零亂，風定猶舞",
      "下句": "郊原初過雨，見數葉零亂，風定猶舞。斜陽掛深樹，映濃愁淺黛，遙山媚嫵。來時舊路，尚岩花、嬌黃半吐。到而今惟有、溪邊流水，見人如故。無語，郵亭深靜，下馬還尋，舊曾題處。無聊倦旅，傷離恨，最愁苦。縱收香藏鏡，他年重到，人面桃花在否？念沉沉小閣幽窗，有時夢去。",
