      "标题": "劍器近",
      "上句": "夜來雨，賴倩得東風吹住",
      "下句": "夜來雨，賴倩得東風吹住。海棠正妖饒處，且留取。悄庭戶，試細聽鶯啼燕語，分明共人愁緒，怕春去。佳樹，翠陰初轉午。重簾未卷，乍睡起，寂寞看風絮。偷彈清淚寄煙波，見江頭故人，為言憔悴如許。彩箋無數，去卻寒暄，到了渾無定據。斷腸落日千山暮。",
