      "标题": "安公子",
      "上句": "",
      "下句": "",
      "原文": "弱柳千絲縷，嫩黃勻遍鴉啼處。寒入羅衣春尚淺，過一番風雨。問燕子來時，綠水橋邊路，曾畫樓、見箇人人否？料靜掩雲窗，塵滿哀弦危柱。庾信愁如許，為誰都著眉端聚。獨立東風彈淚眼，寄煙波東去。念永晝春閑，人倦如何度？閑傍枕、百囀黃鸝語。喚覺來厭厭，殘照依然花塢。",
      "译文": "",
      "注释": "",
      "赏析": "閨中念遠之作。「弱柳千絲縷，嫩黃勻遍鴉啼處」，春柳如絲；結句「喚覺來厭厭，殘照依然花塢」，夢醒殘照，愁緒依然。",
      "链接": ""
