      "下句": "驛外斷橋邊，寂寞開無主。已是黃昏獨自愁，更著風和雨。無意苦爭春，一任群芳妒。零落成泥碾作塵，只有香如故。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
