      "上句": "鬧花深處樓臺，畫簾半卷東風軟",
      "下句": "鬧花深處樓臺，畫簾半卷東風軟。春歸翠陌，平莎茸嫩，垂楊金淺。遲日催花，淡雲閣雨，輕寒輕暖。恨芳菲世界，游人未賞，都付與鶯和燕。寂寞憑高念遠，向南樓、一聲歸雁。金釵鬥草，青絲勒馬，風流雲散。羅綬分香，翠綃封淚，幾多幽怨？正消魂又是，疏煙淡月，子規聲斷。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
