      "原文": "綠樹聽鵜鴃，更那堪、鷓鴣聲住，杜鵑聲切。啼到春歸無啼處，苦恨芳菲都歇。算未抵人間離別，馬上琵琶關塞黑，更長門、翠輦辭金闕，看燕燕，送歸妾。將軍百戰身名裂，向河梁、回頭萬里。故人長絕。易水蕭蕭西風冷，滿座衣冠似雪。正壯士、悲歌未徹。啼鳥還知如許恨，料不啼、清淚長啼血，誰共我，醉明月？",
      "译文": "",
      "注释": "",
      "赏析": "別茂嘉十二弟之作。「綠樹聽鵜鴃，更那堪、鷓鴣聲住，杜鵑聲切」，鳥聲催恨；全詞羅列古人離別典故，結句「誰共我，醉明月」，沉鬱蒼涼，為稼軒詞中奇作。",
