      "上句": "",
      "下句": "",
      "原文": "野塘花落，又匆匆過了清明時節。剗地東風欺客夢，一枕雲屏寒怯。曲岸持觴，垂楊繫馬，此地曾經別。樓空人去，舊游飛燕能說。聞道綺陌東頭，行人曾見，簾底纖纖月。舊恨春江流不盡，新恨雲山千疊。料得明朝，樽前重見，鏡裏花難折。也應驚問，近來多少華髮？",
      "译文": "",
      "注释": "",
      "赏析": "書東流村壁之作。「野塘花落，又匆匆過了清明時節」，野塘春暮；結句「也應驚問，近來多少華髮」，舊地重遊，相見之問，感慨深沉。",
