    "fields": {
      "篇目": "宋词三百首 · 賀新郎 · 辛棄疾 · 賀新郎",
      "标题": "賀新郎",
      "上句": "鳳尾龍香撥，自開元《霓裳曲》罷，幾番風月",
      "下句": "鳳尾龍香撥，自開元《霓裳曲》罷，幾番風月。最苦潯陽江頭客，畫舸亭亭待發。記出塞、黃雲堆雪。馬上離愁三萬里，望昭陽、宮殿孤鴻沒，弦解語，恨難說。遼陽驛使音塵絕，瑣窗寒、輕攏慢拈，淚珠盈睫。推手含情還卻手，一抹《梁州》哀徹。千古事、雲飛煙滅。賀老定場無消息，想沉香亭北繁華歇，彈到此，為嗚咽。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
