      "标题": "摸魚兒",
      "上句": "",
      "下句": "",
      "原文": "更能消幾番風雨，匆匆春又歸去。惜春長怕花開早。何況落紅無數。春且住！見說道、天涯芳草無歸路。怨春不語，算只有殷勤，畫檐珠網，盡日惹飛絮。長門事，準擬佳期又誤，蛾眉曾有人妒。千金縱買相如賦，脈脈此情誰訴？君莫舞！君不見、玉環飛燕皆塵土。閑愁最苦。休去倚危闌，斜陽正在，煙柳斷腸處。",
      "译文": "",
      "注释": "",
      "赏析": "摸魚兒名篇。「更能消幾番風雨，匆匆春又歸去」，惜春之情；結句「休去倚危闌，斜陽正在，煙柳斷腸處」，斜陽煙柳，憂國之思寄託深遠。",
