      "标题": "祝英臺近",
      "上句": "寶釵分，桃葉渡，煙柳暗南浦",
      "下句": "寶釵分，桃葉渡，煙柳暗南浦。怕上層樓，十日九風雨。斷腸片片飛紅，都無人管，更誰勸啼鶯聲住？鬢邊覷，應把花卜歸期，才簪又重數。羅帳燈昏，哽咽夢中語。是他春帶愁來，春歸何處？卻不解帶將愁去。",
