      "原文": "東風夜放花千樹，更吹落、星如雨。寶馬雕車香滿路，鳳簫聲動，玉壺光轉，一夜魚龍舞。蛾兒雪柳黃金縷，笑語盈盈暗香去。眾裡尋他千百度；驀然回首，那人卻在，燈火闌珊處。",
      "译文": "",
