      "原文": "枕簟溪堂冷欲秋，斷雲依水晚來收。紅蓮相倚渾如醉，白鳥無言定自愁。書咄咄，且休休，一丘一壑也風流。不知筋力衰多少，但覺新來懶上樓。",
      "译文": "",
