      "上句": "",
      "下句": "",
      "原文": "鬱孤臺下清江水，中間多少行人淚。西北是長安，可憐無數山。青山遮不住，畢竟江流去。江晚正愁余，山深聞鷓鴣。",
      "译文": "",
      "注释": "",
      "赏析": "書江西造口壁名篇。「鬱孤臺下清江水，中間多少行人淚」，江水流不盡行人淚；「青山遮不住，畢竟江流去」，喻恢復之志不可阻；結句「江晚正愁余，山深聞鷓鴣」，愁緒深沉。",
      "链接": ""
