      "上句": "",
      "下句": "",
      "原文": "燕雁無心，太湖西畔隨雲去。數峰清苦，商略黃昏雨。第四橋邊，擬共天隨住。今何許？憑欄懷古，殘柳參差舞。",
      "译文": "",
