      "原文": "肥水東流無盡期，當初不合種相思。夢中未比丹青見，暗裏忽驚山鳥啼。春未綠，鬢先絲，人閒別久不成悲。誰教歲歲紅蓮夜，兩處沉吟各自知。",
      "译文": "",
      "注释": "",
      "赏析": "元夕有所夢之作。「肥水東流無盡期，當初不合種相思」，悔種相思；結句「誰教歲歲紅蓮夜，兩處沉吟各自知」，兩地沉吟，情深意遠。",
