      "原文": "燕燕輕盈，鶯鶯嬌軟，分明又向華胥見。夜長爭得薄情知？春初早被相思染。別後書辭，別時針線，離魂暗逐郎行遠。淮南皓月冷千山，冥冥歸去無人管。",
      "译文": "",
      "注释": "",
      "赏析": "江上感夢之作。「燕燕輕盈，鶯鶯嬌軟，分明又向華胥見」，夢中相見；結句「淮南皓月冷千山，冥冥歸去無人管」，月冷千山，歸去無依，凄清入骨。",
