      "上句": "",
      "下句": "",
      "原文": "雙槳蓴波，一蓑松雨，暮愁漸滿空闊。呼我盟鷗，翩翩欲下，背人還過木末。那回歸去，蕩雲雪孤舟夜發。傷心重見，依約眉山，黛痕低壓。采香徑裏春寒，老子婆娑，自歌誰答？垂虹西望，飄然引去，此興平生難遏。酒醒波遠，正凝想明璫素襪。如今安在？惟有闌干，伴人一霎。",
      "译文": "",
      "注释": "",
      "赏析": "詠蓴波之作。「雙槳蓴波，一蓑松雨，暮愁漸滿空闊」，蓴波松雨；結句「酒醒波遠，正凝想明璫素襪」，凝想故人，情韻悠遠。",
