      "上句": "",
      "下句": "",
      "原文": "庾郎先自吟愁賦，淒淒更聞私語。露濕銅鋪，苔侵石井，都是曾聽伊處。哀音似訴，正思婦無眠，起尋機杼。曲曲屏山，夜涼獨自甚情緒？西窗又吹暗雨，為誰頻斷續，相和砧杵？候館迎秋，離宮吊月，別有傷心無數。《豳》詩漫與，笑籬落呼燈，世間兒女。寫入琴絲，一聲聲更苦。",
      "译文": "",
