      "赏析": "詠蟬之作，借齊天樂寫秋聲。「庾郎先自吟愁賦，淒淒更聞私語」，蟬聲如訴；結句「寫入琴絲，一聲聲更苦」，聲聲更苦，寄托身世之感。",
