      "上句": "雙槳來時，有人似舊曲桃根桃葉",
      "下句": "雙槳來時，有人似舊曲桃根桃葉。歌扇輕約飛花，蛾眉正奇絕。春漸遠，汀洲自綠，更添了幾聲啼鴃。十里揚州，三生杜牧，前事休說。又還是宮燭分煙，奈愁裏匆匆換時節。都把一襟芳思，與空階榆莢。千萬縷、藏鴉細柳，為玉尊、起舞回雪。想見西出陽關，故人初別。",
