      "上句": "",
      "下句": "",
      "原文": "芳蓮墜粉，疏桐吹綠，庭院暗雨乍歇。無端抱影銷魂處，還見篠牆螢暗，蘚階蛩切。送客重尋西去路，問水面、琵琶誰撥？最可惜、一片江山，總付與啼鴃。長恨相逢未款，而今何事，又對西風離別？渚寒煙淡，棹移人遠，飄渺行舟如葉。想文君望久，倚竹愁生步羅襪。歸來後、翠尊雙飲，下了珠簾，玲瓏閑看月。",
      "译文": "",
      "注释": "",
      "赏析": "湘中送胡德華之作。「芳蓮墜粉，疏桐吹綠，庭院暗雨乍歇」，秋景蕭瑟；結句「歸來後、翠尊雙飲，下了珠簾，玲瓏閑看月」，以對飲看月寫離別後的思念。",
