      "下句": "空城曉角，吹入垂楊陌。馬上單衣寒惻惻。看盡鵝黃嫩綠，都是江南舊相識。正岑寂，明朝又寒食。強攜酒、小橋宅，怕梨花落盡成秋色。燕燕飛來，問春何在？惟有池塘自碧。",
      "原文": "",
