      "标题": "疏影",
      "上句": "",
      "下句": "",
      "原文": "苔枝綴玉，有翠禽小小，枝上同宿。客裏相逢，籬角黃昏，無言自倚修竹。昭君不慣胡沙遠，但暗憶、江南江北。想佩環月夜歸來，化作此花幽獨。猶記深宮舊事，那人正睡裏，飛近蛾綠。莫似春風，不管盈盈，早與安排金屋。還教一片隨波去，又卻怨玉龍哀曲。等恁時、重覓幽香，已入小窗橫幅。",
      "译文": "",
      "注释": "",
      "赏析": "詠梅名篇，與《暗香》並稱。「苔枝綴玉，有翠禽小小，枝上同宿」，梅枝如畫；結句「等恁時、重覓幽香，已入小窗橫幅」，以畫中梅寫尋梅不得，空靈幽獨。",
