      "标题": "翠樓吟",
      "上句": "月冷龍沙，塵清虎落，今年漢酺初賜",
      "下句": "月冷龍沙，塵清虎落，今年漢酺初賜。新翻胡部曲，聽氈幕元戎歌吹。層樓高峙，看欄曲縈紅，檐牙飛翠。人姝麗，粉香吹下，夜寒風細。此地宜有詞仙，擁素雲黃鶴，與君游戲。玉梯凝望久，但芳草萋萋千里。天涯情味，仗酒襏清愁，花消英氣。西山外，晚來還卷，一簾秋霽。",
