      "标题": "杏花天",
      "上句": "",
      "下句": "",
      "原文": "綠絲低拂鴛鴦浦，想桃葉，當時喚渡。又將愁眼與春風，待去，倚蘭橈更少駐。金陵路，鶯吟燕舞。算潮水知人最苦。滿汀芳草不成歸，日暮，更移舟向甚處？",
      "译文": "",
      "注释": "",
      "赏析": "寫春愁之作。「綠絲低拂鴛鴦浦，想桃葉，當時喚渡」，綠絲拂浦；結句「滿汀芳草不成歸，日暮，更移舟向甚處」，日暮移舟，去留無據，迷茫深至。",
