      "原文": "柳暗花明春事深，小闌紅芍藥，已抽簪。雨餘風軟碎鳴禽，遲遲日，猶帶一分陰。往事莫沉吟。身閑時序好、且登臨。舊游無處不堪尋，無尋處，惟有少年心。",
