      "上句": "蘆葉滿汀洲，塞沙帶淺流",
      "下句": "蘆葉滿汀洲，塞沙帶淺流。二十年重過南樓。柳下繫船猶未穩，能幾日，又中秋。黃鶴斷磯頭，故人曾到否？舊江山渾是新愁。欲買桂花同載酒，終不似，少年游。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
