      "标题": "唐多令",
      "上句": "",
      "下句": "",
      "原文": "蘆葉滿汀洲，塞沙帶淺流。二十年重過南樓。柳下繫船猶未穩，能幾日，又中秋。黃鶴斷磯頭，故人曾到否？舊江山渾是新愁。欲買桂花同載酒，終不似，少年游。",
      "译文": "",
      "注释": "",
      "赏析": "重過南樓之作。「蘆葉滿汀洲，塞沙帶淺流」，秋江景物；結句「欲買桂花同載酒，終不似，少年游」，今昔之慨，沉鬱深長。",
      "链接": ""
