      "下句": "一春長費買花錢，日日醉湖邊。玉驄慣識西湖路，驕嘶過、沽酒樓前。紅杏香中簫鼓，綠楊影裏秋千。暖風十里麗人天。花壓鬢雲偏。畫船載取春歸去，餘情寄湖水湖煙。明日重扶殘醉，來尋陌上花鈿。",
