      "标题": "滿庭芳",
      "上句": "月洗高梧，露漙幽草，寶釵樓外秋深",
      "下句": "月洗高梧，露漙幽草，寶釵樓外秋深。土花沿翠，螢火墜牆陰。靜聽寒聲斷續，微韻轉、淒咽悲沉。爭求侶、殷勤勸織，促破曉機心。兒時曾記得，呼燈灌穴，斂步隨音。任滿身花影，猶自追尋。攜向華堂戲鬥，亭臺小、籠巧妝金。今休說，從渠床下，涼夜伴孤吟。",
