      "原文": "幽夢初回，重陰未開，曉色催成疏雨。竹檻氣寒，蕙畹聲搖，新綠暗通南浦。未有人行，才半啟回廊朱戶。無緒，空望極霓旌，錦書難據。苔徑追憶曾游，念誰伴秋千，彩繩芳柱。犀廉黛卷，鳳枕雲孤，應也幾番凝佇。怎得伊來，花霧繞、小堂深處。留住，直到老不教歸去。",
