      "原文": "做冷欺花，將煙困柳，千里偷催春暮。盡日冥迷，愁裏欲飛還住。驚粉重、蝶宿西園，喜泥潤、燕歸南浦。最妨他佳約風流，鈿車不到杜陵路。沉沉江上望極，還被春潮晚急，難尋官渡。隱約遙峰，和淚謝娘眉嫵。臨斷岸、新綠生時，是落紅、帶愁流處。記當日門掩梨花，翦燈深夜語。",
      "译文": "",
      "注释": "",
      "赏析": "詠春雨之作。「做冷欺花，將煙困柳，千里偷催春暮」，春雨欺花困柳；結句「記當日門掩梨花，翦燈深夜語」，雨夜憶舊，情思綿邈。",
