      "标题": "雙雙燕",
      "上句": "過春社了，度簾幕中間，去年塵冷",
      "下句": "過春社了，度簾幕中間，去年塵冷。差池欲住，試入舊巢相並。還相雕梁藻井，又軟語商量不定。飄然快拂花梢，翠尾分開紅影。芳徑，芹泥雨潤，愛貼地爭飛，竟夸輕俊。紅樓歸晚，看足柳昏花暝。應自棲香正穩，便忘了天涯芳信。愁損翠黛雙蛾，日日畫闌獨憑。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
