      "下句": "",
      "原文": "煙光搖縹瓦，望晴檐多風，柳花如酒。錦瑟橫床，想淚痕塵影，鳳弦常下。倦出犀帷，頻夢見、王孫驕馬。諱道相思，偷理綃裙，自驚腰衩。惆悵南樓遙夜，記翠箔張燈，枕肩歌罷。又入銅駝，遍舊家門巷，首詢聲價。可惜東風，將恨與閑花俱謝。記取崔徽模樣，歸來暗寫。",
      "译文": "",
      "注释": "",
      "赏析": "寫閨中春思。「煙光搖縹瓦，望晴檐多風，柳花如酒」，春景如畫；結句「記取崔徽模樣，歸來暗寫」，暗寫伊人，相思入骨。",
