      "篇目": "宋词三百首 · 秋霽 · 史達祖 · 秋霽",
      "标题": "秋霽",
      "上句": "江水蒼蒼，望倦柳愁荷，共感秋色",
      "下句": "江水蒼蒼，望倦柳愁荷，共感秋色。廢閣先涼，古簾空暮，雁程最嫌風力。故園信息，愛渠入眼南山碧。念上國，誰是膾鱸江漢未歸客。還又歲晚、瘦骨臨風，夜聞秋聲，吹動岑寂。露蛩悲、青燈冷屋，翻書愁上鬢毛白。年少俊游渾斷得，但可憐處，無奈苒苒魂驚，采香南浦，翦梅煙驛。",
      "原文": "",
