      "标题": "夜合花",
      "上句": "柳鎖鶯魂，花翻蝶夢，自知愁染潘郎",
      "下句": "柳鎖鶯魂，花翻蝶夢，自知愁染潘郎。輕衫未攬，猶將淚點偷藏。念前事，怯流光，早春窺、酥雨池塘。向消凝裏，梅開半面，情滿徐妝。風絲一寸柔腸，曾在歌邊惹恨，燭底縈香。芳機瑞錦，如何未織鴛鴦。人扶醉，月依牆。是當初、誰敢疏狂！把閑言語，花房夜久，各自思量。",
