      "原文": "晚雨未摧宮樹，可憐閑葉，猶抱涼蟬。短景歸秋，吟思又接愁邊。漏初長、夢魂難禁，人漸老、風月俱寒。想幽歡土花庭甃，蟲網闌干。無端啼蛄攪夜，恨隨團扇，苦近秋蓮。一笛當樓，謝娘懸淚立風前。故園晚、強留詩酒，新雁遠、不致寒暄。隔蒼煙、楚香羅袖，誰伴嬋娟。",
      "译文": "",
      "注释": "",
      "赏析": "秋日懷人之作。「晚雨未摧宮樹，可憐閑葉，猶抱涼蟬」，秋雨閑葉；結句「隔蒼煙、楚香羅袖，誰伴嬋娟」，蒼煙隔望，伊人誰伴。",
