      "译文": "",
      "注释": "",
      "赏析": "秋江懷人之作。「秋江帶雨，寒沙縈水，人瞰畫閣愁獨」，秋江愁獨；結句「應難奈故人天際，望徹淮山，相思無雁足」，雁足難憑，相思無寄。",
