      "原文": "湛湛長空黑，更那堪、斜風細雨，亂愁如織。老眼平生空四海，賴有高樓百尺。看浩蕩、千崖秋色。白髮書生神州淚，盡淒涼不向牛山滴。追往事，去無跡。少年自負凌雲筆，到而今春華落盡，滿懷蕭瑟。常恨世人新意少，愛說南朝狂客。把破帽年年拈出。若對黃花孤負酒，怕黃花也笑人岑寂。鴻北去，日西匿。",
      "译文": "",
