      "下句": "畫樓簾幕卷新晴，掩銀屏，曉寒輕。墜粉飄香，日日喚愁生。暗數十年湖上路，能幾度、著娉婷。年華空自感飄零，擁春酲，對誰醒？天闊雲閑，無處覓簫聲。載酒買花年少事，渾不似、舊心情。",
