      "上句": "生怕倚闌干，閣下溪聲閣外山",
      "下句": "生怕倚闌干，閣下溪聲閣外山。惟有舊時山共水，依然，暮雨朝雲去不還。應是躡飛鸞，月下時時整佩環。月又漸低霜又下，更闌，折得梅花獨自看。",
