      "篇目": "宋词三百首 · 夜合花 · 吳文英 · 夜合花",
      "标题": "夜合花",
      "上句": "柳暝河橋，鶯清臺苑，短策頻惹春香",
      "下句": "柳暝河橋，鶯清臺苑，短策頻惹春香。當時夜泊，溫柔便入深鄉。詞韻窄，酒杯長。翦蠟花、壺箭催忙。共追游處，凌波翠陌，連棹橫塘。十年一夢淒涼，似西湖燕去，吳館巢荒。重來萬感，依前喚酒銀罌。溪雨急，岸花狂，趁殘鴉飛過蒼茫。故人樓上，憑誰指與，芳草斜陽？",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
