      "原文": "斷煙離緒，關心事，斜陽紅隱霜樹。半壺秋水薦黃花，香噀西風雨。縱玉勒、輕飛迅羽，淒涼誰吊荒臺古。記醉踏南屏，彩扇咽寒蟬，倦夢不知蠻素。聊對舊節傳杯，塵箋蠹管，斷闋經歲慵賦。小蟾斜影轉東籬，夜冷殘蛩語。早白髮、緣愁萬縷，驚飆從卷烏紗去，漫細將、茱萸看，但約明年，翠微高處。",
      "译文": "",
      "注释": "",
      "赏析": "重九之作。「斷煙離緒，關心事，斜陽紅隱霜樹」，重九秋景；結句「但約明年，翠微高處」，約明年重九，曠達中含深愁。",
