      "原文": "繡幄鴛鴦柱，紅情密、膩雲低護秦樹。芳根兼倚，花梢鈿合，錦屏人妒。東風睡足交枝，正夢枕瑤釵燕股。障灩蠟、滿照歡叢，嫠蟾冷落羞度。人間萬感幽單，華清慣浴，春盎風露。連鬟并暖，同心共結，向承恩處。憑誰為歌《長恨》？暗殿鎖、秋燈夜語。敘舊期、不負春盟，紅朝翠暮。",
      "译文": "",
