      "上句": "煙波桃葉西陵路，十年斷魂潮尾",
      "下句": "煙波桃葉西陵路，十年斷魂潮尾。古柳重攀，輕鷗聚別，陳跡危亭獨倚。涼颸乍起，渺煙磧飛帆，暮山橫翠。但有江花，共臨秋鏡照憔悴。華堂燭暗送客，眼波回盼處，芳艷流水。素骨凝冰，柔蔥蘸雪，猶憶分瓜深意。清樽未洗，夢不濕行雲，漫沾殘淚。可惜秋宵，亂蛩疏雨裏。",
