      "原文": "小娉婷清鉛素靨，蜂黃暗偷暈。翠翹欹鬢。昨夜冷中庭，月下相認，睡濃更苦淒風緊。驚回心未穩。送曉色、一壺蔥蒨，才知花夢準。湘娥化作此幽芳，凌波路，古岸雲沙遺恨。臨砌影，寒香亂、凍梅藏韻。熏爐畔、旋移傍枕，還又見、玉人垂紺鬒。料喚賞、清華池館，臺杯須滿引。",
      "译文": "",
      "注释": "",
      "赏析": "郭希道送水仙索賦。「小娉婷清鉛素靨，蜂黃暗偷暈」，水仙之姿；結句「料喚賞、清華池館，臺杯須滿引」，賞花之意，情致雅潔。",
