      "标题": "祝英臺近",
      "上句": "剪紅情，裁綠意，花信上釵股",
      "下句": "剪紅情，裁綠意，花信上釵股。殘日東風，不放歲華去。有人添燭西窗，不眠侵曉，笑聲轉新年鶯語。舊樽俎，玉纖曾擘黃柑，柔香繫幽素。歸夢湖邊，還迷鏡中路。可憐千點吳霜，寒消不盡，又相對落梅如雨。",
      "原文": "",
      "译文": "",
