      "标题": "祝英臺近",
      "上句": "",
      "下句": "",
      "原文": "剪紅情，裁綠意，花信上釵股。殘日東風，不放歲華去。有人添燭西窗，不眠侵曉，笑聲轉新年鶯語。舊樽俎，玉纖曾擘黃柑，柔香繫幽素。歸夢湖邊，還迷鏡中路。可憐千點吳霜，寒消不盡，又相對落梅如雨。",
      "译文": "",
      "注释": "",
      "赏析": "除夜立春之作。「剪紅情，裁綠意，花信上釵股」，剪彩迎春；結句「可憐千點吳霜，寒消不盡，又相對落梅如雨」，吳霜未消，落梅如雨，年華之嘆深沉。",
      "链接": ""
