      "原文": "送客吳皋，正試霜夜冷，楓落長橋。望天不盡，背城漸杳，離亭黯黯，恨水迢迢。翠香零落紅衣老，暮愁鎖、殘柳眉梢。念瘦腰、沈郎舊日，曾繫蘭橈。仙人鳳咽瓊簫。悵斷魂送遠，《九辯》難招。醉鬟留盼，小窗翦燭，歌雲載恨，飛上銀霄。素秋不解隨船去，敗紅趁一葉寒濤。夢翠翹，怨鴻料過南譙。",
      "译文": "",
      "注释": "",
      "赏析": "送客之作。「送客吳皋，正試霜夜冷，楓落長橋」，霜夜送客；結句「夢翠翹，怨鴻料過南譙」，夢中尋人，怨恨無窮。",
