      "上句": "宮粉雕痕，仙雲墮影，無人野水荒灣",
      "下句": "宮粉雕痕，仙雲墮影，無人野水荒灣。古石埋香，金沙鎖骨連環。南樓不恨吹橫笛，恨曉風千里關山。半飄零、庭上黃昏，月冷闌干。壽陽空理愁鸞，問誰調玉髓，暗補香瘢？細雨歸鴻，孤山無限春寒。離魂難倩招清些，夢縞衣解佩溪邊。最愁人、啼鳥晴明，葉底清圓。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
