      "原文": "修竹凝妝，垂楊駐馬，憑闌淺畫成圖。山色誰題？樓前有雁斜書。東風緊送斜陽下，弄舊寒、晚酒醒餘。自消凝，能幾花前，頓老相如？傷春不在高樓上，在燈前欹枕，雨外熏爐。怕檥游船，臨流可奈清臞？飛紅若到西湖底，攪翠瀾、總是愁魚。莫重來、吹盡香綿，淚滿平蕪。",
      "译文": "",
      "注释": "",
      "赏析": "豐樂樓分韻之作。「修竹凝妝，垂楊駐馬，憑闌淺畫成圖」，樓前景色；結句「莫重來、吹盡香綿，淚滿平蕪」，香綿吹盡，淚滿平蕪，傷春至深。",
