      "原文": "湖山經醉慣，漬春衫，啼痕酒痕無限。又客長安，嘆斷襟零袂，涴塵誰浣。紫曲門荒，沿敗井、風搖青蔓。對語東鄰，猶是曾巢，謝堂雙燕。春夢人間須斷，但怪得當年，夢緣能短。繡屋秦箏，傍海棠偏愛，夜深開宴。舞歇歌沉，花未減、紅顏先變。佇久河橋欲去，斜陽淚滿。",
      "译文": "",
      "注释": "",
      "赏析": "過都城舊居有感。「湖山經醉慣，漬春衫，啼痕酒痕無限」，舊地重遊；結句「佇久河橋欲去，斜陽淚滿」，斜陽淚滿，故國之思深沉。",
