      "篇目": "宋词三百首 · 八聲甘州 · 吳文英 · 八聲甘州",
      "标题": "八聲甘州",
      "上句": "渺空煙四遠，是何年、青天墜長星",
      "下句": "渺空煙四遠，是何年、青天墜長星。幻蒼崖雲樹，名娃金屋，殘霸宮城。箭徑，酸風射眼，膩水染花腥。時靸雙鴛響，廊葉秋聲。宮裏吳王沉醉，倩五湖倦客，獨釣醒醒。問蒼波無語，華髮奈山青。水涵空、闌干高處，送亂鴉、斜日落漁汀。連呼酒，上琴臺去，秋與雲平。",
      "原文": "",
      "译文": "",
      "注释": "",
