      "原文": "潤玉籠綃，檀櫻倚扇，繡圈猶帶脂香淺。榴心空疊舞裙紅，艾枝應壓愁鬟亂。午夢千山，窗陰一箭，香瘢新褪紅絲腕。隔江人在雨聲中，晚風菰葉生秋怨。",
