      "原文": "晴絲牽緒亂，對滄江斜日，花飛人遠。垂楊暗吳苑，正旗亭煙冷，河橋風暖。蘭情蕙盼，惹相思、春根酒畔。又爭知、吟骨縈消，漸把舊衫重翦。淒斷流紅千浪，缺月孤樓，總難留燕。歌塵凝扇，待憑信，拚分鈿。試挑燈欲寫，還依不忍，箋幅偷和淚卷。寄殘雲剩雨蓬萊，也應夢見。",
      "译文": "",
