      "原文": "池上紅衣伴倚闌，棲鴉常帶夕陽還。殷雲度雨疏桐落，明月生涼寶扇閑。鄉夢窄，水天寬，小窗愁黛淡秋山。吳鴻好為傳歸信，楊柳閶門屋數間。",
      "译文": "",
      "注释": "",
      "赏析": "化度寺作。「池上紅衣伴倚闌，棲鴉常帶夕陽還」，池畔倚闌；結句「吳鴻好為傳歸信，楊柳閶門屋數間」，託鴻傳信，鄉思綿綿。",
