      "标题": "夜游宮",
      "上句": "人去西樓雁杳，敘別夢，揚州一覺",
      "下句": "人去西樓雁杳，敘別夢，揚州一覺。雲淡星疏楚山曉，聽啼烏，立河橋，話未了。雨外蛩聲早，細織就霜絲多少？說與蕭娘未知道，向長安，對秋燈，幾人老？",
