    "fields": {
      "篇目": "宋词三百首 · 湘春夜月 · 黃孝邁 · 湘春夜月",
      "标题": "湘春夜月",
      "上句": "近清明，翠禽枝上消魂",
      "下句": "近清明，翠禽枝上消魂。可惜一片清歌，都付與黃昏。欲共柳花低訴，怕柳花輕薄，不解傷春。念楚鄉旅宿，柔情別緒，誰與溫存？空樽夜泣，青山不語，殘月當門。翠玉樓前，惟是有、一陂湘水，搖蕩湘雲。天長夢短，問甚時、重見桃根？者次第、算人間沒箇并刀，翦斷心上愁痕。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
