      "标题": "青玉案",
      "上句": "",
      "下句": "",
      "原文": "年年社日停針線，怎忍見、雙飛燕？今日江城春已半，一身猶在，亂山深處，寂寞溪橋畔。春衫著破誰針線？點點行行淚痕滿。落日解鞍芳草岸，花無人戴，酒無人勸，醉也無人管。",
      "译文": "",
      "注释": "",
      "赏析": "寫春社懷人。「年年社日停針線，怎忍見、雙飛燕」，社日燕雙飛；結句「花無人戴，酒無人勸，醉也無人管」，三疊「無人」，孤獨入骨，為黃公紹名篇。",
