      "原文": "對西風、鬢搖煙碧，參差前事流水。紫絲羅帶鴛鴦結，的的鏡盟釵誓。渾不記、漫手織回文，幾度欲心碎。安花著葉，奈雨覆雲翻，情寬分窄，石上玉簪脆。朱樓外，愁壓空雲欲墜，月痕猶照無寐。陰晴也只隨天意，枉了玉消香碎。君且醉，君不見長門青草春風淚。一時左計，悔不早荊釵，暮天修竹，頭白倚寒翠。",
      "译文": "",
