      "标题": "永遇樂",
      "上句": "",
      "下句": "",
      "原文": "璧月初晴，黛雲遠淡，春事誰主？禁苑嬌寒，湖堤倦暖，前度遽如許。香塵暗陌，華燈明晝，長是懶攜手去。誰知道斷煙禁夜，滿城似愁風雨。宣和舊日，臨安南渡，芳景猶自如故。緗帙離離，風鬟三五，能賦詞最苦。江南無路，鄜州今夜，此苦又誰知否？空相對殘釭無寐，滿村社鼓。",
      "译文": "",
      "注释": "",
      "赏析": "寫元宵懷舊。「璧月初晴，黛雲遠淡，春事誰主」，元夕月明；結句「空相對殘釭無寐，滿村社鼓」，殘釭社鼓，故國之思，凄涼無限。",
