      "上句": "朱鈿寶玦，天上飛瓊，比人間春別",
      "下句": "朱鈿寶玦，天上飛瓊，比人間春別。江南江北，曾未見、漫擬梨雲梅雪。淮山春晚，問誰識、芳心高潔？消幾番、花落花開，老了玉關豪傑。金壺翦送瓊枝，看一騎紅塵，香度瑤闕。韶華正好，應自喜、初亂長安蜂蝶。杜郎老矣，想舊事花須能說。記少年一夢揚州，二十四橋明月。",
      "原文": "",
