      "下句": "煙水闊，高林弄殘照，晚蜩淒切。碧砧度韻，銀床飄葉。衣濕桐陰露冷，采涼花時賦秋雪。嘆輕別，一襟幽事，砌蟲能說。客思吟商還怯，怨歌長、瓊壺暗缺。翠扇恩疏，紅衣香褪，翻成消歇。玉骨西風，恨最恨、閑卻新涼時節。楚簫咽，誰寄西樓淡月。",
