      "下句": "禁苑東風外，揚暖絲情絮，春思如織。燕約鶯期，惱芳情偏在，翠深紅隙。漠漠香塵隔。沸十里、亂絲叢笛。看畫船盡入西泠，閑卻半湖春色。柳陌，新煙凝碧，映簾底宮眉，堤上游勒。輕暝籠寒，怕梨雲夢冷，杏香愁冪。歌管酬寒食，奈蝶怨良宵岑寂。正滿湖碎月搖花，怎生去得？",
