      "篇目": "宋词三百首 · 花犯 · 周密 · 花犯",
      "标题": "花犯",
      "上句": "楚江湄，湘娥再見，無言灑清淚，淡然春意",
      "下句": "楚江湄，湘娥再見，無言灑清淚，淡然春意。空獨倚東風，芳思誰寄？凌波路冷秋無際。香雲隨步起，漫記得、漢宮仙掌，亭亭明月底。冰絲寫怨更多情，騷人恨，枉賦芳蘭幽芷。春思遠，誰嘆賞國香風味？相將共、歲寒伴侶，小窗靜、沉煙熏翠被。幽夢覺、涓涓清露，一枝燈影裏。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
