      "原文": "夢冷黃金屋，嘆秦箏斜鴻陣裏，素弦塵撲。化作嬌鶯飛歸去，猶認紗窗舊綠。正過雨、荊桃如菽。此恨難平君知否？似瓊臺、湧起彈棋局。消瘦影，嫌明燭。鴛樓碎瀉東西玉，問芳蹤、何時再展？翠釵難卜。待把宮眉橫雲樣，描上生綃畫幅。怕不是新來妝束。彩扇紅牙今都在，恨無人、解聽開元曲。空掩袖，倚寒竹。",
      "译文": "",
      "注释": "",
      "赏析": "寫閨中幽恨。「夢冷黃金屋，嘆秦箏斜鴻陣裏，素弦塵撲」，夢冷金屋；結句「空掩袖，倚寒竹」，掩袖倚竹，幽獨如見。",
