      "上句": "",
      "下句": "",
      "原文": "山空天入海，倚樓望極，風急暮潮初。一簾鳩外雨，幾處閑田，隔水動春鋤。新煙禁柳，想如今、綠到西湖。猶記得、當年深隱，門掩兩三株。愁余，荒洲古漵，斷梗疏萍，更漂流何處？空自覺圍羞帶減，影怯煙孤。長疑即見桃花面，甚近來翻致無書。書縱遠，如何夢也都無。",
      "译文": "",
      "注释": "",
      "赏析": "久客山陰之作。「山空天入海，倚樓望極，風急暮潮初」，山陰暮景；結句「書縱遠，如何夢也都無」，書遠夢無，相思斷絕。",
