      "上句": "",
      "下句": "",
      "原文": "記玉關、踏雪事清游，寒氣脆貂裘。傍枯林古道，長河飲馬，此意悠悠。短夢依然江表，老淚灑西州。一字無題處，落葉都愁。載取白雲歸去，問誰留楚佩，弄影中洲？折蘆花贈遠，零落一身秋。向尋常、野橋流水，待招來、不是舊沙鷗。空懷感，有斜陽處，卻怕登樓。",
      "译文": "",
      "注释": "",
      "赏析": "詠雪之作。「記玉關、踏雪事清游，寒氣脆貂裘」，玉關踏雪；結句「空懷感，有斜陽處，卻怕登樓」，怕登樓見斜陽，黍離之悲，沉鬱蒼涼。",
