      "篇目": "宋词三百首 · 疏影 · 張炎 · 疏影",
      "标题": "疏影",
      "上句": "碧圓自潔，向淺洲遠浦，亭亭清絕",
      "下句": "碧圓自潔，向淺洲遠浦，亭亭清絕。猶有遺簪，不展秋心，能卷幾多炎熱？鴛鴦密語同傾蓋，且莫與、浣紗人說。恐怨歌忽斷花風，碎卻翠雲千疊。回首當年漢舞，怕飛去漫皺，留仙裙摺。戀戀青衫，猶染枯香，還嘆鬢絲飄雪。盤心清露如鉛水，又一夜西風吹折。喜淨看、匹練飛光，倒瀉半湖明月。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
