      "原文": "一襟餘恨宮魂斷，年年翠陰庭樹。乍咽涼柯，還移暗葉，重把離愁深訴。西窗過雨。怪瑤佩流空，玉箏調柱。鏡暗妝殘，為誰嬌鬢尚如許？銅仙鉛淚似洗，嘆移盤去遠，難貯零露。病翼驚秋，枯形閱世，消得斜陽幾度？餘音更苦，甚獨抱清商，頓成淒楚。漫想薰風，柳絲千萬縷。",
      "译文": "",
      "注释": "",
      "赏析": "詠蟬之作。「一襟餘恨宮魂斷，年年翠陰庭樹」，蟬鳴如訴；結句「漫想薰風，柳絲千萬縷」，薰風柳絲，寄託遙深，為詠物寄慨名篇。",
