      "原文": "殘雪庭陰，輕寒簾影，霏霏玉管春葭。小帖金泥，不知春是誰家？相思一夜窗前夢，奈箇人、水隔天遮。但淒然、滿樹幽香，滿地橫斜。江南自是離愁苦，況游驄古道，歸雁平沙。怎得銀箋，殷勤說與年華。如今處處生芳草，縱憑高不見天涯。更消他，幾度東風，幾度飛花。",
      "译文": "",
      "注释": "",
      "赏析": "和周草窗寄越中諸友韻。「殘雪庭陰，輕寒簾影，霏霏玉管春葭」，早春景物；結句「更消他，幾度東風，幾度飛花」，東風飛花，傷春自傷。",
