      "原文": "層綠峨峨，纖瓊皎皎，倒壓波痕清淺。過眼年華，動人幽意，相逢幾番春換。記喚酒尋芳處，盈盈褪妝晚。已消黯，況淒涼近來離思，應忘卻明月，夜深歸輦。荏苒一枝春，恨東風人似天遠。縱有殘花，灑征衣、鉛淚都滿。但殷勤折取，自遣一襟幽怨。",
      "译文": "",
      "注释": "",
      "赏析": "聚景亭梅次草窗韻。「層綠峨峨，纖瓊皎皎，倒壓波痕清淺」，梅影照水；結句「但殷勤折取，自遣一襟幽怨」，折梅自遣，幽怨難平。",
