      "上句": "薄霧濃雲愁永晝，瑞腦消金獸",
      "下句": "薄霧濃雲愁永晝，瑞腦消金獸。佳節又重陽，玉枕紗廚，半夜涼初透。東籬把酒黃昏後，有暗香盈袖。莫道不消魂？簾卷西風，人比黃花瘦。",
