      "原文": "蕭條庭院，有斜風細雨，重門須閉。寵柳嬌花寒食近，種種惱人天氣。險韻詩成，扶頭酒醒，別是閑滋味。征鴻過盡，萬千心事難寄。樓上幾日春寒，簾垂四面，玉闌干慵倚。被冷香消新夢覺，不許愁人不起。清露晨流，新桐初引，多少游春意。日高煙斂，更看今日晴未。",
      "译文": "",
      "注释": "",
      "赏析": "寫春日愁緒。「蕭條庭院，有斜風細雨，重門須閉」，庭院蕭條；結句「日高煙斂，更看今日晴未」，盼晴之情，暗含心事，深婉含蓄。",
      "链接": ""
