      "篇目": "宋词三百首 · 永遇樂 · 李清照 · 永遇樂",
      "标题": "永遇樂",
      "上句": "落日熔金，暮雲合璧，人在何處",
      "下句": "落日熔金，暮雲合璧，人在何處？染柳煙濃，吹梅笛怨，春意知幾許？元宵佳節，融和天氣，次第豈無風雨。來相召、香車寶馬，謝他酒朋詩侶。中州盛日，閨門多暇，記得偏重三五。鋪翠冠兒，撚金雪柳，簇帶爭濟楚。如今憔悴，風鬟霜鬢，怕見夜間出去。不如向簾兒底下，聽人笑語。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
